"use client"

import * as React from "react"
import { ChevronRightIcon, EyeIcon, EyeOffIcon } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"

/* ------------------------------ Shared auth pieces ------------------------------ */

/** Built-in strings of the auth blocks (sign-in, sign-up, waitlist); pass `labels` to translate them. */
export const authSignInLabels = {
  home: (name: string) => `${name} home`,
  continueWith: (provider: string) => `Continue with ${provider}`,
  showPassword: "Show password",
  hidePassword: "Hide password",
}
export type AuthSignInLabels = typeof authSignInLabels

export type AuthProvider = {
  id: string
  label: string
  /** Glyph shown before the label. Defaults to a monogram of the label. */
  icon?: React.ReactNode
}

/** Simple original monogram glyph for a sign-in provider (no third-party marks). */
export function ProviderGlyph({ label, className }: { label: string; className?: string }) {
  return (
    <span
      aria-hidden="true"
      className={cn("grid size-4 shrink-0 place-items-center rounded-full bg-foreground text-[0.5625rem]/none font-semibold text-background", className)}
    >
      {label.charAt(0).toUpperCase()}
    </span>
  )
}

/**
 * Brand mark: a monogram tile plus the product name. Links to `href` when given.
 * Pass `linkComponent` (e.g. your router's `Link`) to render the link with it; defaults to a plain `<a>`.
 */
export function AuthLogo({
  name,
  href,
  linkComponent,
  labels,
}: {
  name: string
  href?: string
  linkComponent?: React.ElementType
  /** Translations of the built-in strings (English by default). */
  labels?: Partial<AuthSignInLabels>
}) {
  const t = { ...authSignInLabels, ...labels }
  const Link = linkComponent ?? "a"
  const content = (
    <>
      <span aria-hidden="true" className="grid size-5 place-items-center rounded-md bg-foreground text-[0.6875rem] font-bold text-background">
        {name.charAt(0).toUpperCase()}
      </span>
      {name}
    </>
  )
  const className = "flex items-center gap-1.5 rounded-md text-[1.0625rem] font-semibold tracking-[-0.03em] text-foreground outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:[--tw-outline-style:solid] focus-visible:outline-ring"
  if (!href) return <span className={className}>{content}</span>
  return (
    <Link href={href} aria-label={t.home(name)} className={className}>
      {content}
    </Link>
  )
}

/** Footer line under an auth card: a prompt and a link ("Don't have an account? Sign up"). */
export function AuthFooterLink({
  prompt,
  label,
  href,
  linkComponent,
}: {
  prompt?: React.ReactNode
  label: React.ReactNode
  href: string
  linkComponent?: React.ElementType
}) {
  const Link = linkComponent ?? "a"
  return (
    <>
      {prompt}
      {prompt ? " " : null}
      <Link href={href} className="rounded-sm font-medium text-foreground outline-none hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:[--tw-outline-style:solid] focus-visible:outline-ring">
        {label}
      </Link>
    </>
  )
}

/** Muted shell around a white panel: logo, title and subtitle on top, a footer line and an optional slot below. */
export function AuthCard({
  logo,
  title,
  subtitle,
  footerText,
  footer,
  className,
  children,
}: {
  logo?: React.ReactNode
  title: string
  subtitle?: React.ReactNode
  /** The line under the panel, e.g. "Don't have an account? Sign up". */
  footerText?: React.ReactNode
  /** Optional neutral slot under the footer line (legal copy, help link, badge). */
  footer?: React.ReactNode
  className?: string
  children: React.ReactNode
}) {
  return (
    <div data-slot="auth-card" className={cn("w-full max-w-100 rounded-xl bg-surface-muted shadow-dialog ring-1 ring-edge/6", className)}>
      <div className="flex flex-col gap-8 rounded-xl bg-surface px-10 pt-8 pb-10 shadow-surface ring-1 ring-edge/4 max-[26rem]:px-6">
        <div className="flex flex-col items-center gap-4 text-center">
          {logo}
          <div>
            <h1 className="text-[1.0625rem]/6 font-bold tracking-[-0.01em] text-balance text-foreground">{title}</h1>
            {subtitle && <p className="mt-1 text-[0.8125rem]/[1.125rem] text-pretty text-subtle">{subtitle}</p>}
          </div>
        </div>
        {children}
      </div>
      {(footerText || footer) && (
        <div className="flex flex-col items-center gap-3 px-8 py-4 text-center text-[0.8125rem] text-subtle">
          {footerText && <p>{footerText}</p>}
          {footer}
        </div>
      )}
    </div>
  )
}

/** Provider buttons: two side by side, otherwise stacked full width. The most recently used one gets a small tag. */
export function ProviderButtons({
  providers,
  recent,
  recentLabel = "Recent",
  disabled,
  onSelect,
  labels,
}: {
  providers: AuthProvider[]
  /** Provider id that gets the `recentLabel` tag. */
  recent?: string
  recentLabel?: string
  disabled?: boolean
  onSelect?: (id: string) => void
  /** Translations of the built-in strings (English by default). */
  labels?: Partial<AuthSignInLabels>
}) {
  const t = { ...authSignInLabels, ...labels }
  if (providers.length === 0) return null
  const grid = providers.length === 2
  return (
    <div className={cn("grid gap-2", grid ? "grid-cols-2 max-[22rem]:grid-cols-1" : "grid-cols-1")}>
      {providers.map((p) => (
        <Button
          key={p.id}
          type="button"
          variant="elevated"
          disabled={disabled}
          onClick={() => onSelect?.(p.id)}
          className="relative w-full gap-2 overflow-visible"
        >
          {p.icon ?? <ProviderGlyph label={p.label} />}
          {grid ? p.label : t.continueWith(p.label)}
          {recent === p.id && (
            <Badge variant="subtle" className="absolute -top-2 -right-1.5 bg-surface-muted">
              {recentLabel}
            </Badge>
          )}
        </Button>
      ))}
    </div>
  )
}

/** "or" rule between provider buttons and the form. */
export function AuthDivider({ label = "or" }: { label?: string }) {
  return (
    <div className="flex items-center gap-4 text-[0.8125rem] text-subtle">
      <span aria-hidden="true" className="h-px flex-1 bg-edge/6" />
      {label}
      <span aria-hidden="true" className="h-px flex-1 bg-edge/6" />
    </div>
  )
}

/** Labelled input; `type="password"` adds a show/hide toggle. */
export function AuthField({
  id,
  label,
  type = "text",
  error,
  className,
  "aria-describedby": describedBy,
  labels,
  ...props
}: Omit<React.ComponentProps<"input">, "id"> & {
  id: string
  label: string
  error?: string
  /** Translations of the built-in strings (English by default). */
  labels?: Partial<AuthSignInLabels>
}) {
  const t = { ...authSignInLabels, ...labels }
  const [show, setShow] = React.useState(false)
  const pw = type === "password"
  const errorId = `${id}-error`
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      <Label htmlFor={id} className="text-[0.8125rem]">
        {label}
      </Label>
      <div className="relative">
        <Input
          id={id}
          name={id}
          type={pw && show ? "text" : type}
          inputMode={type === "email" ? "email" : undefined}
          aria-invalid={error ? true : undefined}
          className={cn(pw && "pr-9")}
          {...props}
          aria-describedby={[describedBy, error ? errorId : undefined].filter(Boolean).join(" ") || undefined}
        />
        {pw && (
          <button
            type="button"
            aria-label={show ? t.hidePassword : t.showPassword}
            aria-pressed={show}
            onClick={() => setShow((s) => !s)}
            className="absolute top-1/2 right-1 grid size-6 -translate-y-1/2 cursor-pointer place-items-center rounded-md text-placeholder transition-colors outline-none hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:[--tw-outline-style:solid] focus-visible:outline-ring"
          >
            {show ? <EyeOffIcon className="size-4" /> : <EyeIcon className="size-4" />}
          </button>
        )}
      </div>
      {error && (
        <p id={errorId} className="text-[0.8125rem]/[1.125rem] text-destructive-text">
          {error}
        </p>
      )}
    </div>
  )
}

/** Full-width primary submit with a trailing chevron, swapped for a spinner while pending. */
export function AuthSubmit({ pending, children }: { pending?: boolean; children: React.ReactNode }) {
  return (
    <Button type="submit" variant="primary" disabled={pending} className="w-full gap-1">
      {pending ? <Spinner className="size-3.5" /> : null}
      {children}
      {!pending && <ChevronRightIcon aria-hidden="true" className="size-3.5 opacity-70" />}
    </Button>
  )
}

/** Runs an optional async handler while tracking a pending flag. */
export function usePending() {
  const [pending, setPending] = React.useState(false)
  const run = React.useCallback(async (fn?: () => void | Promise<void>) => {
    if (!fn) return
    setPending(true)
    try {
      await fn()
    } finally {
      setPending(false)
    }
  }, [])
  return [pending, run] as const
}

/* ---------------------------------- Sign in ---------------------------------- */

/**
 * Sign-in card: optional logo, provider buttons, email field, primary continue, an optional alternative method and a link to sign up.
 * Pass `linkComponent` (e.g. your router's `Link`) to render the sign-up link with it; defaults to a plain `<a>`.
 */
export function AuthSignIn({
  logo,
  title = "Sign in",
  subtitle,
  providers = [],
  recentProvider,
  recentLabel,
  emailLabel = "Email address",
  emailPlaceholder = "you@example.com",
  submitLabel = "Continue",
  alternativeLabel,
  onAlternative,
  signUpHref,
  signUpPrompt = "Don't have an account?",
  signUpLabel = "Sign up",
  linkComponent,
  error,
  footer,
  onSubmit,
  onProvider,
  labels,
  className,
}: {
  logo?: React.ReactNode
  title?: string
  subtitle?: React.ReactNode
  /** Social or SSO providers shown above the form. Empty hides the buttons and the divider. */
  providers?: AuthProvider[]
  /** Provider id that gets the `recentLabel` tag. */
  recentProvider?: string
  /** Tag text for the recent provider. Defaults to "Recent". */
  recentLabel?: string
  emailLabel?: string
  emailPlaceholder?: string
  submitLabel?: string
  /** Text button under the form for another method (magic link, security key…). Shown only with `onAlternative`. */
  alternativeLabel?: string
  onAlternative?: () => void
  /** Omit to hide the sign-up line. */
  signUpHref?: string
  signUpPrompt?: string
  signUpLabel?: string
  /** Component used for links, e.g. Next.js or Inertia `Link`. Defaults to `"a"`. */
  linkComponent?: React.ElementType
  /** Error shown under the email field. */
  error?: string
  /** Optional neutral slot under the footer line. */
  footer?: React.ReactNode
  onSubmit?: (values: { email: string }) => void | Promise<void>
  onProvider?: (id: string) => void
  /** Translations of the built-in strings (English by default). */
  labels?: Partial<AuthSignInLabels>
  className?: string
}) {
  const id = React.useId()
  const [email, setEmail] = React.useState("")
  const [pending, run] = usePending()
  return (
    <AuthCard
      logo={logo}
      title={title}
      subtitle={subtitle}
      className={className}
      footer={footer}
      footerText={signUpHref ? <AuthFooterLink prompt={signUpPrompt} label={signUpLabel} href={signUpHref} linkComponent={linkComponent} /> : undefined}
    >
      {providers.length > 0 && (
        <>
          <ProviderButtons providers={providers} recent={recentProvider} recentLabel={recentLabel} disabled={pending} onSelect={onProvider} labels={labels} />
          <AuthDivider />
        </>
      )}
      <form
        className="flex flex-col gap-8"
        onSubmit={(e) => {
          e.preventDefault()
          run(() => onSubmit?.({ email }))
        }}
      >
        <AuthField
          id={`${id}-email`}
          name="email"
          label={emailLabel}
          type="email"
          autoComplete="email"
          placeholder={emailPlaceholder}
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          error={error}
          labels={labels}
          required
        />
        <AuthSubmit pending={pending}>{submitLabel}</AuthSubmit>
      </form>
      {alternativeLabel && onAlternative && (
        <div className="-mt-4 text-center">
          <button
            type="button"
            onClick={onAlternative}
            disabled={pending}
            className="cursor-pointer rounded-sm text-[0.8125rem] font-medium text-foreground outline-none hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:[--tw-outline-style:solid] focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50"
          >
            {alternativeLabel}
          </button>
        </div>
      )}
    </AuthCard>
  )
}
